-- دفعة ثانية من المواقع السياحية الموثّقة. شغّلها بعد الملف الأول. آمنة للتكرار.
begin;
insert into public.places (id,name,category,status,region_id,region_name,description,alerts,source_name,source_url,verified_at)
values ('shobak-castle','قلعة الشوبك','tourism','published','maan','معان','قلعة بناها الصليبيون ووسّعها المماليك، شيّدها بلدوين الأول ملك القدس عام 1115 خلال حملة إلى المنطقة. تقع على الجانب الشرقي من وادي عربة بجوار بلدة الشوبك، على جبل صخري مخروطي.',array['تحقق من ساعات الدخول والأسعار الحالية من الجهة المشغّلة قبل الزيارة'],'Wikipedia','https://en.wikipedia.org/wiki/Shobak_Castle',now())
on conflict (id) do update set name=excluded.name, region_id=excluded.region_id, region_name=excluded.region_name, description=excluded.description, alerts=excluded.alerts, source_name=excluded.source_name, source_url=excluded.source_url, verified_at=excluded.verified_at, updated_at=now();
insert into public.places (id,name,category,status,region_id,region_name,description,alerts,source_name,source_url,verified_at)
values ('pella-tabaqat-fahl','بيلا (طبقة فحل)','tourism','published','irbid','إربد','مدينة أثرية في شمال غرب الأردن بمحافظة إربد على السفوح الشرقية لغور الأردن، تبعد نحو 27 كم جنوب بحيرة طبريا ونحو 130 كم شمال عمّان. سُكنت شبه متواصلة منذ العصر الحجري الحديث عبر العصور الكنعانية والهلنستية والرومانية والبيزنطية والإسلامية، وكانت من مدن الديكابولس. الموقع ملك للحكومة وتديره دائرة الآثار العامة وقد نُقّب جزء منه فقط.',array['تحقق من ساعات الدخول والأسعار الحالية من الجهة المشغّلة قبل الزيارة'],'Wikipedia','https://en.wikipedia.org/wiki/Pella,_Jordan',now())
on conflict (id) do update set name=excluded.name, region_id=excluded.region_id, region_name=excluded.region_name, description=excluded.description, alerts=excluded.alerts, source_name=excluded.source_name, source_url=excluded.source_url, verified_at=excluded.verified_at, updated_at=now();
insert into public.places (id,name,category,status,region_id,region_name,description,alerts,source_name,source_url,verified_at)
values ('umm-al-jimal','أم الجمال','tourism','published','mafraq','المفرق','قرية في شمال الأردن تبعد نحو 17 كم شرق المفرق وأقل من 10 كم عن الحدود السورية في منطقة حوران، وفيها أطلال بلدة بيزنطية وإسلامية مبكرة بُنيت بالحجر البازلتي البركاني. يعود الموقع إلى الفترة النبطية حتى العباسية؛ بدأ في القرن الأول الميلادي وهُجر نحو سنة 900 ثم أُعيد سكنه في القرن العشرين.',array['تحقق من ساعات الدخول والأسعار الحالية من الجهة المشغّلة قبل الزيارة'],'Wikipedia','https://en.wikipedia.org/wiki/Umm_al-Jimal',now())
on conflict (id) do update set name=excluded.name, region_id=excluded.region_id, region_name=excluded.region_name, description=excluded.description, alerts=excluded.alerts, source_name=excluded.source_name, source_url=excluded.source_url, verified_at=excluded.verified_at, updated_at=now();
insert into public.places (id,name,category,status,region_id,region_name,description,alerts,source_name,source_url,verified_at)
values ('wadi-mujib','محمية وادي الموجب','tourism','published',NULL,NULL,'نهر وأخدود ضيق ومحمية في شرق البحر الميت، تبعد نحو 90 كم جنوب عمّان. يصب الوادي في البحر الميت على نحو 420 مترًا تحت مستوى سطح البحر، وترتفع المحمية إلى 1277 مترًا في بعض المواضع. أنشأتها الجمعية الملكية لحماية الطبيعة عام 1987 وأعلنتها اليونسكو محمية محيط حيوي عام 2011، ومساحتها 212 كم².',array['تحقق من ساعات الدخول والأسعار الحالية من الجهة المشغّلة قبل الزيارة'],'Wikipedia','https://en.wikipedia.org/wiki/Wadi_Mujib',now())
on conflict (id) do update set name=excluded.name, region_id=excluded.region_id, region_name=excluded.region_name, description=excluded.description, alerts=excluded.alerts, source_name=excluded.source_name, source_url=excluded.source_url, verified_at=excluded.verified_at, updated_at=now();
insert into public.places (id,name,category,status,region_id,region_name,description,alerts,source_name,source_url,verified_at)
values ('amman-roman-theatre','المدرج الروماني في عمّان','tourism','published','amman','عمّان','مسرح روماني في عمّان من القرن الثاني الميلادي، يدل نقش يوناني على أنه بُني تكريمًا للإمبراطور أنطونينوس بيوس (138–161م) حين كانت المدينة تُسمى فيلادلفيا. يتسع لنحو 6000 شخص، ويقع شرق عمّان عند سفح جبل الجوفة على تلة تقابل جبل القلعة.',array['تحقق من ساعات الدخول والأسعار الحالية من الجهة المشغّلة قبل الزيارة'],'Wikipedia','https://en.wikipedia.org/wiki/Roman_Theatre_(Amman)',now())
on conflict (id) do update set name=excluded.name, region_id=excluded.region_id, region_name=excluded.region_name, description=excluded.description, alerts=excluded.alerts, source_name=excluded.source_name, source_url=excluded.source_url, verified_at=excluded.verified_at, updated_at=now();
insert into public.places (id,name,category,status,region_id,region_name,description,alerts,source_name,source_url,verified_at)
values ('dead-sea','البحر الميت','tourism','published',NULL,NULL,'بحيرة مغلقة شديدة الملوحة بلا مخرج، وهي أعمق بحيرة عالية الملوحة في العالم. يبلغ سطحها نحو 440 مترًا تحت مستوى سطح البحر (439.78م في 2025)، وملوحتها نحو 34.2% أي نحو 9.6 أضعاف ملوحة المحيط. يحدّها الأردن من الشرق والضفة الغربية من الغرب، وشواطئها أخفض نقطة يابسة على الأرض.',array['تحقق من ساعات الدخول والأسعار الحالية من الجهة المشغّلة قبل الزيارة'],'Wikipedia','https://en.wikipedia.org/wiki/Dead_Sea',now())
on conflict (id) do update set name=excluded.name, region_id=excluded.region_id, region_name=excluded.region_name, description=excluded.description, alerts=excluded.alerts, source_name=excluded.source_name, source_url=excluded.source_url, verified_at=excluded.verified_at, updated_at=now();
insert into public.places (id,name,category,status,region_id,region_name,description,alerts,source_name,source_url,verified_at)
values ('aqaba','العقبة','tourism','published','aqaba','العقبة','المدينة الساحلية الوحيدة في الأردن، في أقصى الجنوب عند الطرف الشمالي الشرقي للبحر الأحمر، ومركز محافظة العقبة وأكبر مدن خليج العقبة. ميناؤها هو الميناء البحري الوحيد في البلاد. فيها أكثر من ثلاثين موقع غوص رئيسيًا مناسبة لمختلف المستويات، وتمتد الشعاب المرجانية الحافية على أكثر من 25 كم باتجاه الحدود السعودية.',array['تحقق من ساعات الدخول والأسعار الحالية من الجهة المشغّلة قبل الزيارة'],'Wikipedia','https://en.wikipedia.org/wiki/Aqaba',now())
on conflict (id) do update set name=excluded.name, region_id=excluded.region_id, region_name=excluded.region_name, description=excluded.description, alerts=excluded.alerts, source_name=excluded.source_name, source_url=excluded.source_url, verified_at=excluded.verified_at, updated_at=now();
insert into public.places (id,name,category,status,region_id,region_name,description,alerts,source_name,source_url,verified_at)
values ('azraq-wetland-reserve','محمية الأزرق للأراضي الرطبة','tourism','published','zarqa','الزرقاء','محمية طبيعية في بلدة الأزرق بالبادية الشرقية، وصفتها ويكيبيديا بأنها واحة للطيور المهاجرة، وهي موقع رامسار منذ 10 يناير 1977. أنشأتها الجمعية الملكية لحماية الطبيعة عام 1978 وما زالت تديرها. سُجّل فيها نحو 280 نوعًا مهاجرًا، وجفّت ينابيعها الطبيعية عام 1992 فغادرت معظم الطيور، وأعادت الجمعية جزئيًا ترميم الأراضي الرطبة فعادت عدة أنواع.',array['تحقق من ساعات الدخول والأسعار الحالية من الجهة المشغّلة قبل الزيارة'],'Wikipedia','https://en.wikipedia.org/wiki/Azraq_Wetland_Reserve',now())
on conflict (id) do update set name=excluded.name, region_id=excluded.region_id, region_name=excluded.region_name, description=excluded.description, alerts=excluded.alerts, source_name=excluded.source_name, source_url=excluded.source_url, verified_at=excluded.verified_at, updated_at=now();
insert into public.places (id,name,category,status,region_id,region_name,description,alerts,source_name,source_url,verified_at)
values ('machaerus-mukawir','قلعة مكاور (ماكيروس)','tourism','published','madaba','مادبا','قصر وحصن صحراوي على قمة تلة في قرية مكاور بمحافظة مادبا، يطل على البحر الميت. بناه الملك الحشمونائي ألكسندر يانايوس نحو 90 ق.م ودمّره الجنرال الروماني غابينيوس عام 57 ق.م، ثم أعاد هيرودس الكبير بناءه وتوسيعه. تذكر روايات يوسيفوس والعهد الجديد أن يوحنا المعمدان سُجن فيه وقُطع رأسه نحو عام 32م.',array['تحقق من ساعات الدخول والأسعار الحالية من الجهة المشغّلة قبل الزيارة'],'Wikipedia','https://en.wikipedia.org/wiki/Machaerus',now())
