insert into public.places (id,name,category,status,region_id,region_name,description,alerts,source_name,source_url,verified_at)
values ('the-jordan-museum','المتحف الأردني','tourism','published','amman','عمّان','أكبر متحف في الأردن، متحف فني وأثري افتُتح رسميًا عام 2014 بعد بدء الإنشاء عام 2009، في حي رأس العين قرب وسط عمّان. من مقتنياته تماثيل عين غزال التي يبلغ عمرها نحو 9000 سنة وتُعد من أقدم التماثيل البشرية، ومخطوطات البحر الميت ومنها اللفافة النحاسية.',array['تحقق من ساعات الدخول والأسعار الحالية من الجهة المشغّلة قبل الزيارة'],'Wikipedia','https://en.wikipedia.org/wiki/The_Jordan_Museum',now())
